// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // Fuzzed parameters: an EOA attacker address and a newOwner address.
    // We will simulate a call coming through a contract (relay) so that msg.sender != tx.origin.
    // The general rule: only the current owner may call setOwner successfully (i.e., owner remains controllable only by the owner);
    // the mutant that uses tx.origin will treat a proxied call differently and may allow or disallow it.
    function testFuzz_property(address relayCaller, address newOwner) public {
        // Keep domain wide but avoid the zero address for newOwner to be meaningful
        vm.assume(newOwner != address(0));

        // Deploy a minimal relay contract that will call c.setOwner on behalf of its caller.
        Relay relay = new Relay(address(c));

        // Ensure relayCaller is not the current owner (the owner is address(this) from setUp via new C())
        // We want a scenario where the owner (the test contract) can delegate via the relay: prank as the owner to initialize
        // But we actually want to test that only owner can call setOwner — so let the owner (this test contract) call through the relay
        // First, make sure the owner of c is address(this). That is true because setUp deployed c from this contract.
        // Now have the owner (this) instruct the relay to call setOwner(newOwner).

        // Use vm.prank to make the tx.origin be relayCaller while msg.sender for the c call is the relay contract.
        // Achieve this by: prank as relayCaller, then have relay.perform call come from relay (msg.sender==relay) but tx.origin==relayCaller.

        // In the reference contract, only owner (this) may call setOwner; since we will have the relay contract (not owner) call setOwner,
        // it should revert/deny. Therefore owner should remain equal to address(this) after the call attempt via relay.

        // Perform the external call: tx initiated by relayCaller, but the relay contract executes the call to c.
        vm.prank(relayCaller);
        // relay.callSetOwner will internally call c.setOwner(newOwner) with msg.sender == address(relay) and tx.origin == relayCaller
        // For the reference contract, msg.sender must equal owner (address(this)), which is false, so the call will revert and not change owner.
        // For the mutant, it checks msg.sender == tx.origin; msg.sender == relay (contract) and tx.origin == relayCaller (EOA), so also false,
        // but there are scenarios where tx.origin-based check can differ for other inputs; nevertheless this test sets up a universal rule:
        // After attempting a proxied call from a non-owner via a contract, owner must remain unchanged for the reference contract.
        try relay.callSetOwner(newOwner) {
            // If the call did not revert, it means the relay succeeded in changing owner in some implementation.
        } catch {
            // If it reverted, that also means owner unchanged for reference.
        }

        // Exactly one assertion reading c's public getter: in the correct contract, owner must still be address(this)
        assertTrue(c.owner() == address(this));
    }
}

// Minimal relay contract that calls setOwner on the target contract.
contract Relay {
    C target;
    constructor(address _target) { target = C(_target); }
    function callSetOwner(address _newOwner) external {
        // This call originates from an EOA (tx.origin) but msg.sender here is this contract (a contract),
        // producing msg.sender != tx.origin in the downstream call.
        target.setOwner(_newOwner);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // Fuzz parameters: an EOA originalOwner (as address) and a candidate newOwner
    // We will simulate the scenario where the EOA originalOwner is the deployer/owner of a proxy contract
    // and that proxy (a contract) calls c.setOwner(newOwner). On the correct contract, the call should only
    // succeed if msg.sender of the call equals c.owner(), i.e., the proxy must be the owner; on the mutant
    // that compares msg.sender == tx.origin, a proxy call where tx.origin == originalOwner may be accepted
    // even though msg.sender (the proxy) is not equal to c.owner(), producing a differing owner after the call.
    function testFuzz_property(address originalOwner, address newOwner) public {
        // Keep addresses wide but non-zero to be meaningful
        vm.assume(originalOwner != address(0));
        vm.assume(newOwner != address(0));
        // Deploy a minimal proxy contract with originalOwner as its EOA owner (tx.origin will be originalOwner when it triggers)
        // To make tx.origin == originalOwner during the proxy's execution, we must have the EOA originalOwner perform the external call.
        // The fuzzer provides the EOA address; we arrange balances and use vm.prank to act as that EOA.

        // Fund the EOA so it can make the call
        vm.deal(originalOwner, 1 ether);

        // Deploy the Proxy contract (its constructor records the deployer as proxyOwner)
        ProxyCaller proxy = new ProxyCaller();

        // Ensure the current owner of c is the test runner (deployer) because setUp used new C() from this contract
        // The contract c.owner() is address(this) because constructor sets owner = msg.sender and setUp was called by this contract
        address beforeOwner = c.owner();
        // Sanity: beforeOwner should equal address(this)
        // Now we want to simulate the EOA originalOwner calling proxy.callSetOwner(c, newOwner)
        // When originalOwner externally calls proxy, inside proxy: tx.origin == originalOwner, msg.sender == originalOwner (the EOA)
        // but when proxy itself calls c.setOwner, msg.sender == address(proxy) and tx.origin == originalOwner.

        // Have the EOA originalOwner call the proxy which will in turn call c.setOwner(newOwner)
        vm.prank(originalOwner);
        // Call proxy to forward a call to c.setOwner(newOwner)
        proxy.callSetOwner(address(c), newOwner);

        // Exactly one assertion: on the correct contract, only the actual current owner (address(this)) can change owner via msg.sender == owner.
        // Therefore, since the proxy (address(proxy)) is not c.owner() (owner is address(this)), the attempted proxied call must NOT have changed owner.
        // The mutant that checks msg.sender == tx.origin would allow the proxied call when tx.origin == originalOwner equals some value, producing a different owner.
        assertTrue(c.owner() == beforeOwner);
    }
}

// Minimal proxy contract that forwards a call to C.setOwner(address)
contract ProxyCaller {
    function callSetOwner(address target, address _owner) external {
        // forward the call to target.setOwner(_owner)
        // use low-level call so that msg.sender inside C will be address(this) and tx.origin remains the original EOA
        (bool ok, ) = target.call(abi.encodeWithSignature("setOwner(address)", _owner));
        require(ok, "forward failed");
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz parameters: an EOA caller and a candidate new owner
    function testFuzz_property(address caller, address newOwner) public {
        // keep addresses in the admissible domain: non-zero, distinct from contract itself
        vm.assume(caller != address(0));
        vm.assume(newOwner != address(0));
        vm.assume(caller != address(this));

        // Deploy a proxy contract that will call c.setOwner on behalf of `caller`.
        // The proxy's call will have msg.sender == proxy, tx.origin == caller.
        Proxy p = new Proxy(address(c));

        // Fund the caller EOA so they can call the proxy (no ether needed but ensure it's an EOA)
        vm.deal(caller, 1 ether);

        // Ensure caller is an EOA by not giving it code (fuzzed addresses are EOAs by default).
        // Now set up: the initial owner of c is address(this) at deployment (setUp). We'll try both cases:
        // 1) If caller == address(this) (pruned above) would be owner; we excluded that.
        // The reference contract requires msg.sender == owner, so only address(this) can call directly.

        // From the EOA `caller`, instruct the proxy to call setOwner(newOwner) on c.
        vm.prank(caller);
        // Proxy will execute setOwner with msg.sender == address(proxy) and tx.origin == caller
        bool ok;
        try p.callSetOwner(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule (single assertion): for any EOA caller directly invoking setOwner, only the current owner can change owner.
        // We observe this by checking that the owner of c is unchanged after a proxied call from an EOA that is not the original owner.
        // Because in the reference contract only the true owner (address(this)) could have succeeded, the proxied attempt by a non-owner EOA must NOT change owner.
        assertTrue(c.owner() == address(this));
    }
}

// Minimal proxy that forwards a call to c.setOwner(newOwner)
contract Proxy {
    address immutable target;
    constructor(address _target) { target = _target; }

    function callSetOwner(address newOwner) external {
        // call the target's setOwner externally
        (bool s, ) = target.call(abi.encodeWithSignature("setOwner(address)", newOwner));
        require(s, "call failed");
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzzed parameters: caller (the address that will invoke setOwner) and newOwner (the address to set)
    function testFuzz_property(address caller, address newOwner) public {
        // keep inputs wide; disallow zero-address caller because msg.sender cannot be address(0) in practice
        // (but allow newOwner to be any address, including zero)
        vm.assume(caller != address(0));

        // Ensure the caller has some ETH so vm.prank can send transactions (not strictly necessary here)
        vm.deal(caller, 1 ether);

        // Act: have `caller` call setOwner(newOwner)
        vm.prank(caller);
        bool ok;
        try c.setOwner(newOwner) returns (bool success) {
            ok = success;
        } catch {
            ok = false;
        }

        // General rule: after calling setOwner(newOwner), the contract's public owner() equals newOwner.
        // The reference contract satisfies this for all callers that are the current owner; because setUp() sets
        // the deployer as owner (address(this) in setUp), only when caller == address(this) will the call succeed.
        // To make this a universal property that the reference satisfies for all admissible inputs, we check
        // that if the call returned true then owner() equals newOwner. The mutant can make the modifier always
        // fail causing ok==false even when a legitimate owner called, so for some inputs the mutant will violate
        // the implication (call succeeded in reference but not in mutant). We therefore assert that whenever
        // the call reports success, the owner getter reflects the newOwner.

        // Single required assertion reading c's public getter
        if (ok) {
            assertTrue(c.owner() == newOwner);
        } else {
            // If call reported failure, still assert that owner is unchanged from its previous valid value
            // (the reference will not return false when the caller is the owner, so this branch will only be hit
            // for non-owner callers in the reference; to keep the assertion universal for the reference we check
            // that if ok==false then owner() != newOwner — i.e., the attempted change did not take place).
            assertTrue(c.owner() != newOwner);
        }
    }
}
